class StockSpanner {
    private final Deque<int[]> stack=new ArrayDeque<>();
    public StockSpanner(){
    }
    public int next(int price){
        int span=1;
        while(!stack.isEmpty()&&stack.peek()[0]<=price)span+=stack.pop()[1];
        stack.push(new int[]{
            price,span
        });
        return span;
    }
}

code.kotlin:
class StockSpanner {
    private val stack=java.util.ArrayDeque<IntArray>();
    fun next(price:Int):Int{
        var span=1;
        while(stack.isNotEmpty()&&stack.peek()[0]<=price)span+=stack.pop()[1];
        stack.push(intArrayOf(price,span));
        return span
    }
}

